P = ["Günümüz meseleleri","Para ve kazanç"]
M = [
{"id":"altinvadeli","yol":P,"baslik":"Altını kredi kartıyla veya veresiye almak","ar":"شراء الذهب بالتقسيط",
 "hanefi":"Altın ve gümüş ile para arasındaki alışveriş “sarf” akdidir ve meclis içinde karşılıklı teslim (peşinlik) şarttır; altını taksitle veya veresiye almak ribâ’n-nesîe olduğu için caiz değildir. Kredi kartıyla tek çekimde alışverişte banka satıcıya ödemeyi derhâl yaptığından, alıcı da kartı kendi borcu olarak üstlendiğinden günümüz âlimlerinin çoğu bunu caiz görür; taksitli kredi kartıyla altın almak ise caiz değildir. Takı olarak işlenmiş altın konusunda farklı görüşler bulunsa da ihtiyat, peşin almaktır.",
 "mez":{"maliki":["Veresiye caiz değil","İşlenmiş altında ihtilaf vardır."],
        "safii":["Veresiye caiz değil","Peşinlik şarttır."],
        "hanbeli":["Veresiye caiz değil","İbn Teymiyye işlenmiş altında vadeyi caiz görmüştür."]},
 "sebep":"Kâğıt paranın altın ile değişiminde ribâ hükümlerinin uygulanması ve işlenmiş altının (ziynet) “mal” mı “semen” mi sayıldığı.",
 "delil":[["hadis","“Altın altınla… peşin peşine…”",hadis("الذهب بالذهب والفضة بالفضة مثلا بمثل يدا بيد"),"Müslim, Müsâkāt, 81."],
          ["hadis","“Cinsler farklı olunca peşin olmak şartıyla dilediğiniz gibi satın.”",hadis("فإذا اختلفت هذه الأصناف فبيعوا كيف شئتم إذا كان يدا بيد"),"Müslim, Müsâkāt, 81."]],
 "usul":"Semeniyet illetini taşıyan iki maldan biri diğeriyle değişilirken vade (nesîe) ribâ olur."},
{"id":"ikinciel","yol":P,"baslik":"Ayıplı malı kusurunu söylemeden satmak","ar":"كتمان العيب في البيع",
 "hanefi":"Satıcının malın bildiği kusurunu alıcıdan gizlemesi aldatma ve haramdır; kusur açıklanmalıdır. Alıcı satış anında bilmediği bir kusuru sonradan fark ederse malı geri verme hakkı (hıyâr-ı ayb) vardır. İkinci el araba, telefon, ev satışında kilometre, hasar kaydı, tamir geçmişi gibi bilgilerin gizlenmesi veya değiştirilmesi de bu yasağa girer. “Her türlü kusuruyla satıyorum” denilerek satılan malda ise alıcı bunu kabul etmiş olur.",
 "mez":{"maliki":["Aynı","Ayıptan beraat şartı sınırlı geçerlidir."],
        "safii":["Aynı","Satıcının bilmediği gizli kusurlar dışında beraat şartı geçerli değildir."],
        "hanbeli":["Aynı","Bilinen ayıbı gizlemek haramdır."]},
 "sebep":"Ayıptan beraat şartının (kusurdan sorumlu olmama) geçerlilik sınırı.",
 "delil":[["hadis","“Ayıplı olduğunu bildiği malı açıklamadan satmak helal değildir.”",hadis("لا يحل لمسلم باع من أخيه بيعا فيه عيب إلا بينه له"),"İbn Mâce, Ticârât, 45."],
          ["hadis","Islak buğdayı alta koyan satıcı",hadis("من غشنا فليس منا"),"Müslim, Îmân, 164."]],
 "usul":"Akitte esas, malın kusursuz olmasıdır (selâmet şartı örfen vardır); bu şartın ihlali alıcıya fesih hakkı verir."},
{"id":"haramkazanc","yol":P,"baslik":"Haram kazançla verilen hediye ve davet","ar":"قبول هدية من كسبه حرام",
 "hanefi":"Kazancının tamamı haram olduğu bilinen kişinin hediyesini kabul etmek ve davetine gitmek caiz değildir. Kazancının çoğu helal olan veya helali ile haramı karışık olan kişinin hediyesi, aksi bilinmedikçe kabul edilebilir; verdiği şeyin bizzat haramdan olduğu bilinirse kabul edilmez. Müslümanlar hakkında aslolan hüsnüzandır; ayrıntılı araştırma yapmak gerekmez.",
 "mez":{"maliki":["Benzer","Çoğu haram olanın hediyesi mekruhtur."],
        "safii":["Benzer","Şüpheli maldan kaçınmak verâdır."],
        "hanbeli":["Benzer","Karışık maldan yemek mekruhtur."]},
 "sebep":"Helal ve haramın karıştığı maldaki ölçü: çoğunluğun mu, aynın mı esas alınacağı.",
 "delil":[["hadis","Helal-haram arası şüpheliler",hadis("فمن اتقى الشبهات استبرأ لدينه وعرضه"),"Buhârî, Îmân, 39; Müslim, Müsâkāt, 107."]],
 "usul":"“Hüküm çoğunluğa göredir” (li’l-ekseri hükmü’l-kül) ve “Müslümanın işi doğruluğa hamledilir” kaideleri."},
{"id":"isyeriharam","yol":P,"baslik":"Haram iş kolunda çalışmak","ar":"العمل في الحرام",
 "hanefi":"İçki, kumar, faizli bankacılık, müstehcen yayın gibi bizzat haram olan işleri yapmak ve bunlara doğrudan yardım etmek caiz değildir; bu işlerden kazanılan ücret helal değildir. Faaliyeti büyük ölçüde helal olan bir iş yerinde doğrudan haramla ilgisi olmayan bir görev yapmak (temizlik, güvenlik, muhasebenin helal kısmı gibi) ise caizdir. Haram bir işte çalışan kişi helal bir iş bulmak için gayret etmelidir.",
 "mez":{"maliki":["Aynı","Haramda yardımlaşmak haramdır."],
        "safii":["Aynı","Doğrudan katkı haramdır."],
        "hanbeli":["Aynı","Hıristiyanın içkisini taşımak için ücret alınmaz."]},
 "sebep":"Haramın doğrudan işlenmesi ile dolaylı sebep olunması arasındaki fark.",
 "delil":[["ayet","Mâide 5:2","./#5-2","“…Günah ve düşmanlık üzerinde yardımlaşmayın.”"],
          ["hadis","İçki ile ilgili on kişiye lanet",hadis("لعن رسول الله صلى الله عليه وسلم في الخمر عشرة"),"Tirmizî, Büyû‘, 59: içkiyi sıkan, taşıyan, satan…"]],
 "usul":"Hanefîler doğrudan sebep (mübaşeret) ile uzak sebep (tesebbüb) arasında ayrım yapar; uzak sebepte günah, failin kendisine aittir."},
{"id":"bagis","yol":P,"baslik":"Bağış toplamak ve bağışın amacı dışında kullanılması","ar":"جمع التبرعات وصرفها",
 "hanefi":"Dernek, vakıf veya kişiler tarafından belirli bir amaç için (cami yapımı, kurban, burs, deprem yardımı) toplanan bağışlar emanettir; bağışçının belirttiği amaç dışında kullanılamaz. Amaç gerçekleşmiş veya imkânsızlaşmışsa, bağışçılardan izin alınarak veya en yakın benzer hayra harcanır. Bağış toplayanın idari giderleri şeffaf ve makul ölçüde olmalıdır; bağışlardan şahsi çıkar sağlamak emanete hıyanettir. Zekâtın şartlarına uygun yerlere verilmesine ayrıca dikkat edilmelidir.",
 "mez":{"maliki":["Aynı","Bağışçının şartı geçerlidir."],
        "safii":["Aynı","Vâkıfın şartı şâriin nassı gibidir."],
        "hanbeli":["Aynı","Amaca en yakın yere harcanır."]},
 "sebep":"Bağışlayanın şartının bağlayıcılığı ve amacın gerçekleşmemesi hâlinde ne yapılacağı.",
 "delil":[["ayet","Nisâ 4:58","./#4-58","“Allah size emanetleri ehline vermenizi… emrediyor.”"],
          ["ayet","Enfâl 8:27","./#8-27","“…Bile bile emanetlerinize hıyanet etmeyin.”"]],
 "usul":"“Vâkıfın şartı, şâriin nassı gibidir”; amaç ortadan kalkınca en yakın amaç (ekrab ile’l-garaz) esas alınır."},
]
